  str_n32_multiline_story_review = "Eventos passados",
  str_n32_multiline_know = "Tá bom.",
  str_n32_multiline_branch_tips = "{1}, desacelerar!\nMinha bola de cristal está me dizendo que passamos <color=#f16a4b>{2}</color> lugar(es) que vale(m) a pena conferir... Será que tem?\nDevemos voltar e descobrir?",
