  str_n32_multiline_14_name = "Estudo Mansão",
  str_n32_multiline_15_name = "salão da mansão",
  str_n32_multiline_16_name = "Vazio Quebrado",
  str_n32_multiline_17_name = "Fora dos Portões",
  str_n32_multiline_18_name = "Montague",
  str_n32_multiline_19_name = "garota ruiva",
  str_n32_multiline_20_name = "Senhorita Roshee",
  str_n32_multiline_21_name = "Artigos de papelaria",
  str_n32_multiline_22_name = "Não é você",
  str_n32_multiline_23_name = "Casa Montague",
  str_n32_multiline_24_name = "Profecia",
  str_n32_multiline_1_name_desc = "Joshua se transforma em um monstro e ataca você. Jakine apressadamente lança um feitiço para teletransportar todos para fora do Cristal da Memória Eterna, e quando você volta a si...",
  str_n32_multiline_2_name_desc = "...",
  str_n32_multiline_3_name_desc = "Você se separa para seguir dois caminhos separados, de acordo com o plano, e espera pelo Dark Angel aparecer. No entanto, as coisas quase nunca são tão simples agora, não é?",
  str_n32_multiline_4_name_desc = "Um dragão negro como breu e o misterioso exército rebelde... Um bom show está prestes a começar.",
  str_n32_multiline_5_name_desc = "O tempo flui para trás novamente, as velhas memórias e novos obstáculos aguardam sua chegada.",
  str_n32_multiline_6_name_desc = "Sua festa se encontra com Lady Joshua novamente, mas a história toma um rumo inesperado sem você por perto.",
  str_n32_multiline_7_name_desc = "Como Schwartz assume o escuro Angel em uma batalha individual, a rebelião está prestes a começar, e o dragão está pronto para voar, desta vez...",
  str_n32_multiline_8_name_desc = "Desta vez, Mia sobrevive. Alguém mais teria tanta sorte?",
  str_n32_multiline_9_name_desc = "...",
  str_n32_multiline_10_name_desc = "A tragédia ainda dá um jeito de atacar, mas você não tem tempo para parar e descansar.",
  str_n32_multiline_11_name_desc = "O plano para a última viagem no tempo foi feito. Agora, uma corrida contra o tempo começa.",
  str_n32_multiline_12_name_desc = "Você localiza a Escuridão Angel, mas apaziguá-la pode ser mais difícil do que o esperado...",
  str_n32_multiline_13_name_desc = "O bater das asas de uma borboleta pode desencadear um furacão. Em breve, todas as suas peças estarão alinhadas.",
  str_n32_multiline_14_name_desc = "...",
  str_n32_multiline_15_name_desc = "Apenas a Rainha Branca permanece no tabuleiro, e ela está apostando tudo em um último movimento desesperado.",
  str_n32_multiline_16_name_desc = "...",
  str_n32_multiline_17_name_desc = "Convidado para o grande salão de Schwartz Mansão, você ouve alguém falando do outro lado de uma porta.",
  str_n32_multiline_18_name_desc = "Enquanto você se prepara para partir Schwartz Mansão, você encontra uma pilha de cartas queimadas no meio de uma área gramada no jardim dos fundos...",
  str_n32_multiline_19_name_desc = "Em uma pequena estrada que leva a Schwartz Mansion, uma garota ruiva de repente bloqueia o caminho de Sharona.",
  str_n32_multiline_20_name_desc = "Escondido perto da praça central, você inadvertidamente ouve uma conversa entre dois velhos amigos.",
  str_n32_multiline_21_name_desc = "Em uma rua em Uptown, duas pessoas aparentemente não relacionadas estão conversando sobre algo que merece sua atenção...",
  str_n32_multiline_22_name_desc = "Em uma pequena estrada que leva a Schwartz Mansão, uma torre alta desmorona com um estrondo...",
  str_n32_multiline_23_name_desc = "Em meio ao caos, você descobre dois nobres presos no local.",
  str_n32_multiline_24_name_desc = "Em uma pequena estrada que leva a Schwartz Mansão, uma torre alta desabou...",
  str_n32_multiline_1_name_desc_long = "Jakine falhou. Você não pode deixar o Cristal da Memória Eterna, mas rastrear com sucesso o tempo antes do desfile começar. Joshua, que se tornou um monstro conhecido como Dark Angel, ataca você mais uma vez. Depois de lutar contra ela, você tenta ir embora, apesar de sua crescente desesperança, mas ainda não faz nenhum progresso. Neste momento, outro Joshua parece.",
  str_n32_multiline_2_name_desc_long = "Joshua explica toda a história para você. Acontece que Joshua nunca morreu, mas confinou a si mesma e à personalidade incontrolável que se desprendeu de sua semente para o Cristal da Memória Eterna. Para salvar Joshua e deixar este lugar, você faz um plano para suprimir o Dark Angel.",
  str_n32_multiline_3_name_desc_long = "Você se divide em dois grupos de acordo com o plano. Mia chega às arquibancadas, enquanto os outros atraem com sucesso o Dark Angel fora. As coisas parecem estar indo perfeitamente quando a rebelião começa cedo por razões desconhecidas. Inimigos estranhos e um dragão de aparência estranha atacam as arquibancadas, mergulhando seu plano no caos.",
  str_n32_multiline_4_name_desc_long = "Você derrota o Escuro Angel, mas a situação ao seu redor cai mais fundo no desespero a cada segundo. Forças rebeldes, um dragão voador e uma mania crescente se espalham continuamente pela multidão, até mesmo transformando o rosto de Joshua em uma imagem irreconhecível de ferocidade. Seus companheiros são devorados pela boca da corrupção, um após o outro, e assim que você afunda no desespero, Jakine lança o feitiço de viagem no tempo mais uma vez...",
  str_n32_multiline_5_name_desc_long = "O tempo flui para trás e todos no jardim estão mais uma vez engajados na batalha contra as Trevas. Angel. Só que você ainda está sendo perseguido pelos guardas com suas expressões sinistras... O que realmente está acontecendo aqui? Enquanto você se esconde, agarrando-se à vida querida, você se perde em contemplação.",
  str_n32_multiline_6_name_desc_long = "Semelhante à primeira vez que você viajou no tempo, todos se encontram Joshua novamente, mas desta vez, parece que Schwartz e Joshua estão em desacordo. Por esta razão, Caleb fica ao lado de Jakine, e Schwartz enfrenta o escuro Angel sozinho.",
  str_n32_multiline_7_name_desc_long = "Na batalha individual que se seguiu, Schwartz e o escuro Angel são iguais, mas o Dark Angel de repente fala com a voz de Joshua, condenando o comportamento irresponsável de Schwartz para com sua família. Ao mesmo tempo, a rebelião começa e você percebe que deve aproveitar a oportunidade para se reagrupar com os outros. No entanto, é neste momento que você testemunha o Dark Angel impedindo o dragão de atacar as arquibancadas.",
  str_n32_multiline_8_name_desc_long = "Desta vez, Mia sobrevive. No entanto, jovem Carleen é afetada devido a um ferimento e opta por tirar a própria vida para proteger sua família. O espírito de Mia está prestes a desmoronar com a situação, em tal momento, o moribundo Dark Angel leva Mia em seus braços e a segura com força. É neste momento que Schwartz se convence de que a Escuridão Angel é de fato sua esposa.",
  str_n32_multiline_9_name_desc_long = "Na mansão, Joshua explica a verdade para Caleb. Acontece que Joshua é um assassino da facção oposta de Schwartz, e não a irmã biológica de Caleb. Ela tenta persuadir Caleb a ajudá-la a eliminar os outros e, embora Caleb não duvide da identidade de Joshua, ele não está disposto a ajudá-la e acaba sendo morto por Joshua.",
  str_n32_multiline_10_name_desc_long = "Você e Mia chegue à mansão para encontrar a residência em caos total e, com a ajuda da Sra. Rot, você consegue escapar com Jakine. Você esclarece aproximadamente a verdade do assunto organizando a inteligência obtida por meio das duas excursões de viagem - essa viagem no tempo será sua última oportunidade.",
  str_n32_multiline_11_name_desc_long = "Você foge de seus perseguidores conforme planejado e vem antes Joshua conforme marcado. Um novo jogo de xadrez está prestes a começar.",
  str_n32_multiline_12_name_desc_long = "Você tenta aplacar o Escuro Angel cantando a música que ela cantou para Mia. Isso lembra o escuro Angel de seu passado, onde a tentativa de assassinato falhou e ela foi conquistada pelo jovem Schwartz... Suas memórias são vívidas, tornando ainda mais difícil para ela perdoar Schwartz.",
  str_n32_multiline_13_name_desc_long = "Schwartz não consegue ver o escuro Angel mas encontra os soldados perseguindo você. Você guia todos para as arquibancadas antes dos ataques do dragão e consegue combatê-lo. Mia também consolou o Escuro Angel, enquanto a Sra. Rot fica com Joshua, e as coisas mudam drasticamente para melhor.",
  str_n32_multiline_14_name_desc_long = "A verdade pode ser difícil de aceitar, mas para seguir em frente, devemos aprender a enfrentar tudo. Calebe, Schwartz, o escuro Angel, Mia, e Ms. Rot... À medida que a batalha final se aproxima, todos têm suas próprias verdades firmemente gravadas em seus corações.",
  str_n32_multiline_15_name_desc_long = "Você trava uma batalha decisiva contra o Demônio Branco e a leva à beira da derrota. O Demônio Branco pretende arrastá-lo para o túmulo com ela, enquanto o Demônio das Trevas Angel escolhe enfrentar o Demônio Branco sozinha após se reconciliar com sua família. Os dois eus divididos finalmente se encontram novamente.",
  str_n32_multiline_16_name_desc_long = "Você sai com sucesso do Cristal da Memória Eterna após salvar Joshua. No entanto, Joshua parece ter perdido todas as suas memórias e opta por embarcar em uma nova jornada sozinha. Quando é difícil enfrentar o presente, muitas vezes as pessoas optam por mergulhar no passado como forma de fuga. Somente quando as pessoas recuperarem a coragem de viver é que poderemos avançar para um novo futuro.",
  str_n32_multiline_17_name_desc_long = "...",
  str_n32_multiline_18_name_desc_long = "...",
  str_n32_multiline_19_name_desc_long = "...",
  str_n32_multiline_20_name_desc_long = "...",
  str_n32_multiline_21_name_desc_long = "...",
  str_n32_multiline_22_name_desc_long = "...",
  str_n32_multiline_23_name_desc_long = "...",
  str_n32_multiline_24_name_desc_long = "...",
  str_n32_multiline_doc_lock = "Vamos nos aventurar com ousadia. Talvez tenhamos alguns encontros inesperados ao longo do caminho.",
  str_n32_multiline_doc_role_1 = "Srta. Blanc",
  str_n32_multiline_doc_role_2 = "Joshua",
  str_n32_multiline_doc_role_3 = "Sharona",
  str_n32_multiline_doc_role_4 = "Otto",
  str_n32_multiline_doc_roledesc_1 = "O ex-capitão da Nightwatch, cuja idade é um mistério.\nEla foi ferida e recuou durante a Batalha de Umbraton no calendário matinal do ano de 1988, após ser sitiada pelo Darkover, e mais tarde se tornou uma guia turística elegante.\nAté hoje, as lendas de sua antiga identidade - Sra. A podridão, portadora da morte e da destruição, ainda permanece nos cantos silenciosos de Lumopolis...",
  str_n32_multiline_doc_roledesc_2 = "A filha de um renomado estudioso e a \"falecida esposa\" do Senhor da Cidade. Naquela época, sob imensa pressão, ela se apaixonou e se casou com Schwartz. No entanto, seu pai não conseguiu ver o dia do casamento, pois morreu em um incêndio.\nNo Morning Calendar 1992, foi anunciado oficialmente que Joshua havia falecido por doença.",
  str_n32_multiline_doc_roledesc_3 = "Nascida em Lumopolis, ela foi informada ainda jovem que seus pais haviam falecido e foram levados aos cuidados dos anciãos da família Kartima. Em Morning Calendar 1988, a família Kartima foi procurada por Lumopolis por instigar um golpe, e Sharona felizmente conseguiu escapar da cidade. Mais tarde, ela se juntou às forças da coalizão para participar de um contra-ataque contra Darkover e, eventualmente, tornou-se Comandante da Legião Illumina.",
  str_n32_multiline_doc_roledesc_4 = "Nasceu na poderosa família Troy, cuja principal esfera de influência é o Conselho dos Anciões. Depois que o City Lord anterior foi assassinado, rumores começaram a apontar o dedo para a família Troy, mas esses rumores rapidamente se dissiparam. Ele havia planejado treinar sua sobrinha como sua sucessora, no entanto, ela foi posteriormente registrada oficialmente como falecida.",
  str_n32_multiline_doc_name_1 = "Histórico da Sra. Blanc",
  str_n32_multiline_doc_name_2 = "Carta aos Montecchios",
  str_n32_multiline_doc_name_3 = "O conto da garota ruiva",
  str_n32_multiline_doc_name_4 = "Roshee retorna ao caminho correto",
  str_n32_multiline_doc_name_5 = "A Carta Ardente",
  str_n32_multiline_doc_name_6 = "A Garota Ruiva e o Ancião",
  str_n32_multiline_doc_name_7 = "Casa Montague",
  str_n32_multiline_doc_name_8 = "Donzela da Profecia",
  str_n32_multiline_doc_tips_1 = "Eventos passados Antecedentes da Sra. Blanc desbloqueados",
  str_n32_multiline_doc_tips_2 = "Carta de Eventos Passados para os Montagues desbloqueada",
  str_n32_multiline_doc_tips_3 = "Eventos anteriores O conto da garota ruiva desbloqueado",
  str_n32_multiline_doc_tips_4 = "Eventos anteriores Roshee retorna ao caminho correto desbloqueado",
  str_n32_multiline_doc_tips_5 = "Eventos passados The Burning Letter desbloqueado",
  str_n32_multiline_doc_tips_6 = "Eventos anteriores A garota ruiva e o ancião desbloqueados",
  str_n32_multiline_doc_tips_7 = "Eventos anteriores House Montague desbloqueado",
  str_n32_multiline_doc_tips_8 = "Eventos anteriores Donzela da Profecia desbloqueada",
  str_n32_multiline_doc_desc_1 = "Ms. Blanc é um parente distante de Lady Joshua, no entanto, os dois não são parentes de sangue. Ms. Blanc mostrou um talento surpreendente desde tenra idade, mas sofreu a frustração de não ter onde colocar sua habilidade em bom uso. Diante da bênção confusa de ter um filho talentoso, seus pais não tiveram escolha a não ser colocá-la nas mãos de Caleb, mas foi depois disso que ela inesperadamente conheceu Lady. Joshua. Os dois se deram bem, estabelecendo um forte relacionamento e conversando animadamente desde o primeiro encontro. Como resultado, Joshua ensinado Ms. Blanc por muitos anos.",
  str_n32_multiline_doc_desc_2 = "Em uma pilha de cartas queimadas está escondida uma carta para o Filho dos Montagues, escrita pelo pai de Caleb. Na carta, o pai de Caleb parece ter feito uma espécie de resolução, oferecendo desejos sinceros ao destinatário.",
  str_n32_multiline_doc_desc_3 = "Uma mãe com Dragonkin despertou deu à luz duas filhas. Sua herança a fez perder o controle e ela foi morta por sua família. Para proteger seu dragão prestes a nascer, a filha mais velha escolheu vagar até se estabelecer em Umbraton. A filha mais nova cresceu sem saber que sua mãe foi morta por sua tribo.",
  str_n32_multiline_doc_desc_4 = "Embora Otto não tenha filhos, ele sempre tratou sua sobrinha Roshee, que mais tarde se tornou um dos Quatro Anjos, Michael, como se fosse sua própria filha. Quando ela era mais jovem, Roshee costumava gostar de vagar pelos becos e ruas, pegando ladrões e outros vilões variados, mas sob a orientação de Otto, ela gradualmente voltou sua mente para coisas maiores. No calendário matinal do ano de 1988, Roshee de repente fugiu de casa sem o menor aviso.",
  str_n32_multiline_doc_desc_5 = "A razão pela qual a sobrinha de Otto, Roshee, fugiu de casa foi que ela recebeu uma nota listando todas as evidências indicando que seu tio Otto foi quem colocou Eclipsites em Lumopolis um ano antes disso e instigou a revolta. Roshee não podia aceitar que isso fosse verdade, acreditando que seu tio nunca faria tal coisa. Portanto, Roshee deixou uma carta para sua amiga Sharona, e ela decidiu ficar longe de sua família e se juntar à força expedicionária...",
  str_n32_multiline_doc_desc_6 = "A garota ruiva derrubou uma torre alta na qual um ancião da família Kartima foi preso por ir contra Mime. Para surpresa da ruiva, a mais velha disse a mesma coisa que sua mãe havia dito: \"Não é você quem vai salvar a família Kartima.\" A garota ruiva sabia que a mais velha estava esperando por sua irmã Sharona, mas ela sentiu que essas coisas não importavam mais para ela.",
  str_n32_multiline_doc_desc_7 = "Pirro, Gautier... Montague. Estes são os nomes das casas que se rebelaram contra o Schwartz família - nomes que acabaram se perdendo no tempo. O ódio cegou os sobreviventes, tornando-os peões ideais para aspirantes a conspiradores.",
  str_n32_multiline_doc_desc_8 = "Sharona correu para o ancião ao lado da torre desmoronada. O ancião disse a ela que, de acordo com a profecia, Sharona foi o único que poderia salvar a família Kartima. ele desejou Sharona herdar o Azure A Flame Katana foi transmitida de geração em geração pelos anciãos da família Kartima, e para finalmente carregar o fardo de garantir a futura glória de sua linhagem.",
  str_n32_multiline_doc_lockdesc_1 = "Quando <color=#ffe062>Rachaduras</color>, ouça o que o guarda está dizendo na entrada do <color=#ffe062>salão de Schwartz Mansão</color>.",
  str_n32_multiline_doc_lockdesc_2 = "Quando <color=#ffe062>Rachaduras</color>, preste atenção ao que está sob seus pés a caminho do <color=#ffe062>Praça central</color>...",
  str_n32_multiline_doc_lockdesc_3 = "Quando <color=#ffe062>Rachaduras</color>, alguém parece estar bloqueando seu caminho quando você está saindo do <color=#ffe062>Praça central</color>...",
  str_n32_multiline_doc_lockdesc_4 = "Quando as coisas começam <color=#ffe062>estourando</color>, você parece ser capaz de ouvir alguns sons quando se esconde ao redor do <color=#ffe062>Praça central</color>...",
  str_n32_multiline_doc_lockdesc_5 = "Quando as coisas começam <color=#ffe062>estourando</color>, procure figuras familiares ao caminhar pelos caminhos ao redor do <color=#ffe062>Praça central</color>.",
  str_n32_multiline_doc_lockdesc_6 = "Quando as coisas começam <color=#ffe062>estourando</color>, preste atenção nas formas dos prédios ao sair do <color=#ffe062>Praça central</color>.",
  str_n32_multiline_doc_lockdesc_7 = "Quando as coisas começam <color=#ffe062>Desmoronando</color>, apontam uma rota de fuga para dois nobres no <color=#ffe062>Praça central</color>.",
  str_n32_multiline_doc_lockdesc_8 = "Quando as coisas começam <color=#ffe062>Desmoronando</color>, preste atenção à torre em colapso ao sair do <color=#ffe062>Praça central</color>.",
  str_n32_multiline_doc_unlock_1 = "Fazer Ms. Blanc e senhora Joshua compartilhar tal história?!",
  str_n32_multiline_doc_unlock_2 = "Como o pai de Caleb poderia ter escrito uma carta dessas?!",
  str_n32_multiline_doc_unlock_3 = "A história da garota ruiva é realmente apenas um conto?",
  str_n32_multiline_doc_unlock_4 = "Parece que Otto também tem suas fraquezas inesperadas...",
  str_n32_multiline_doc_unlock_5 = "A sobrinha fugiu de casa por causa do que Otto fez?",
  str_n32_multiline_doc_unlock_6 = "A garota ruiva é na verdade a irmã biológica de Sharona, Leona?!",
  str_n32_multiline_doc_unlock_7 = "Esses nomes agora perdidos no tempo... Não parecem familiares?",
  str_n32_multiline_doc_unlock_8 = "Sharona finalmente conheceu a pessoa que estava esperando por ela...",
  str_n32_multiline_lock_tips1 = "Eu não tenho nenhuma pista ainda.",
  str_n32_multiline_lock_tips2 = "Vá e procure o local indicado.",
  str_n32_multiline_desc_1 = "O passado foi reiniciado. O cristal aguarda sua decisão.",
  str_n32_multiline_desc_2 = "Continue indo e voltando até recuperar a verdade na destruição.",
  str_n32_multiline_desc_3 = "Descubra onde a luz e a escuridão terminam ao fazer sua escolha final.",
  str_n32_multiline_desc_pass = "Embarque em uma jornada. Sempre nos lembraremos da ode cantada à cidade do céu.",
  str_n32_multiline_name_1 = "Rachaduras",
  str_n32_multiline_name_2 = "estourando",
  str_n32_multiline_name_3 = "Desmoronando",
  str_n32_multiline_main_forlder_pass = "A redefinição atual terminou",
  str_n32_multiline_main_folder_unpass = "O tempo está sendo zerado",
  str_n32_multiline_branch_folder_pass = "Experimentou todos os encontros",
  str_n32_multiline_branch_folder_unpass_normal = "Ainda há encontros que você <color=#fea62d>perdido</color>.",
  str_n32_multiline_branch_folder_unpass_format = "Você perdeu <color=#fea62d>{1}</color> encontro(s).",
  str_n32_multiline_dialogue_chat_title_1 = "Fora dos Portões",
  str_n32_multiline_dialogue_chat_title_2 = "Montague",
  str_n32_multiline_dialogue_chat_title_3 = "garota ruiva",
  str_n32_multiline_dialogue_chat_title_4 = "Senhorita Roshee",
  str_n32_multiline_dialogue_chat_title_5 = "Artigos de papelaria",
  str_n32_multiline_dialogue_chat_title_6 = "Não é você",
  str_n32_multiline_dialogue_chat_title_7 = "Casa Montague",
  str_n32_multiline_dialogue_chat_title_8 = "Profecia",
  str_n32_multiline_dialogue_chat_indesc_1 = "Fora do salão de Schwartz Manor, uma empregada e um soldado estão conversando.",
